  "print.howIntro": "یہ ایپ ان پرنٹرز سے منسلک ہوتی ہے جو آپ کے پاس پہلے سے ہیں — یہ خود پرنٹر نہیں ہے۔ اس تک پہنچنے کے چار طریقے ہیں، اور لیبلز ان میں سے کسی پر بھی دونوں پلانز پر پرنٹ ہوتے ہیں۔ پیکنگ سلپس، خریداری کے آرڈرز، سپلائر دستاویزات اور رپورٹس صرف Business کے لیے ہیں، کنکشن چاہے کوئی بھی ہو۔",
