  "print.howBluetoothBody": "اس صفحے سے، ڈیسک ٹاپ Chrome یا Edge پر اور Android Chrome پر: اپنا لیبل پرنٹر منتخب کریں اور لیبلز براہ راست اس پر چلے جاتے ہیں۔ یہ iOS Safari میں کام نہیں کرتا — iPhone پر Bluetooth پرنٹنگ موبائل ایپ کے ساتھ آتی ہے۔ جو پرنٹر صرف Zebra ZPL یا Brother کی اپنی زبان بولتا ہے وہ اس صفحے کے بھیجے گئے لیبلز نہیں سمجھے گا؛ اسے کام کرتا کہنے سے پہلے اصل پرنٹرز کے خلاف جانچا جاتا ہے۔",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "پرنٹر کو اپنی دکان کے Wi-Fi پر انسٹال کریں، پھر پرنٹ بٹن استعمال کریں — یہ دکان کے نیٹ ورک پر، اس کمپیوٹر پر انسٹال شدہ پرنٹر کے ذریعے پرنٹ کرتا ہے۔ iPhone پر AirPrint پہلے سے موجود ہے: اسی Wi-Fi پر موجود AirPrint پرنٹر پرنٹ شیٹ میں بس ظاہر ہو جاتا ہے، نہ تار درکار نہ ایپ، اور ایپ کو AirPrint کے لیے مخصوص کوڈ کی ضرورت نہیں۔ پرنٹر کو AirPrint کی حمایت کرنی چاہیے (بیشتر نئے کرتے ہیں) اور فون اور پرنٹر کو اسی Wi-Fi پر ہونا چاہیے۔",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "پرنٹر کو Ethernet تار سے اپنے دکان کے نیٹ ورک سے جوڑیں، اسے کمپیوٹر پر انسٹال کریں، اور پرنٹ بٹن کے ذریعے پرنٹ کریں۔ Ethernet ڈیسک ٹاپ اور کمپیوٹر کا راستہ ہے — iPhones Ethernet تاریں استعمال نہیں کرتے۔",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "پرنٹر کو اس کی تار سے کمپیوٹر میں لگائیں اور پرنٹ بٹن استعمال کریں — یہ وہاں انسٹال شدہ پرنٹر کے ذریعے پرنٹ کرتا ہے۔ USB OTG کیبل والے Android فون پر، اوپر والا USB بٹن براہ راست پرنٹر سے بات کرتا ہے۔ iPhones براہ راست USB پر پرنٹ نہیں کر سکتے — وہاں کوئی WebUSB نہیں — اس لیے Wi-Fi / AirPrint استعمال کریں، یا موبائل ایپ سے Bluetooth۔",
  "print.howCordsLead": "تاریں پھر بھی iPhones کی خدمت کرتی ہیں، ایک قدم ہٹ کر۔",
  "print.howCordsBody": "دکان کے کمپیوٹر میں لگا USB پرنٹر، یا نیٹ ورک سے جڑا Ethernet پرنٹر، آپ کے iPhone پر دکان کے Wi-Fi کے ذریعے ظاہر ہوتا ہے (AirPrint / مشترکہ پرنٹر) — تاریں پرنٹر کو مضبوطی سے نیٹ ورک پر لاتی ہیں، اور فون اس تک وائرلیس پہنچتا ہے۔",
  "print.howOfflineLead": "اگر انٹرنیٹ بند ہو جائے،",
  "print.howOfflineBody": "تو اس صفحے پر پہلے سے موجود لیبلز اور دستاویزات پھر بھی پرنٹ ہوتی ہیں — پرنٹ بٹن، لیبلز PDF، Bluetooth اور USB کو کسی کنکشن کی ضرورت نہیں۔ انٹرنیٹ جس چیز کے لیے درکار ہے وہ صفحہ اور اس کی مصنوعات کو لوڈ کرنا ہے۔ مکمل آف لائن موڈ (بغیر کسی کنکشن کے ایپ میں کام کرنا) ایک الگ، بڑی تعمیر ہے اور یہاں اس کا دعویٰ نہیں کیا جاتا۔",
