  "payroll.dd.steps.body": "1. آپ کو ایک کاروباری بینک اکاؤنٹ چاہیے جو ACH ادائیگیاں بھیج سکے۔ 2. ہر ٹیم ممبر سے دستخط شدہ اجازت فارم جمع کریں - ایک منسوخ شدہ چیک نمبروں کی تصدیق میں مدد کرتا ہے۔ 3. تنخواہ کے دن سے 2-3 کاروباری دن پہلے پے رول بھیجیں تاکہ رقم وقت پر پہنچ جائے۔ 4. زیادہ تر ریاستوں میں ٹیم ممبر کی تحریری رضامندی ضروری ہے۔ یہ ایپ فارم جمع کرتی ہے اور مراحل میں آپ کی رہنمائی کرتی ہے - رقم اصل میں بھیجنا آپ کے اپنے بینک کے ذریعے ہوتا ہے۔",
