  "support.contextNote": "تاکہ ہم مسئلہ تلاش کر سکیں، آپ کے نوٹ میں خود ہی وہ صفحہ شامل ہوتا ہے جس پر آپ ہیں، آپ کا کاروبار اور کردار اگر منتخب ہو، آپ کا پلان، آپ کی ایپ زبان، اور آپ کس قسم کا فون یا براؤزر استعمال کر رہے ہیں۔ اس میں آپ کی پروڈکٹس، اسٹاک یا فروخت کبھی شامل نہیں ہوتیں۔",
  "support.description": "کچھ خراب ہے، کچھ غلط لگتا ہے، یا شیئر کرنے کے لیے کوئی خیال؟ ہمیں یہاں بتائیں — آپ کا نوٹ سیدھا ایپ کے پیچھے ٹیم کے پاس جاتا ہے۔",
  "support.errorGeneric": "یہ نہیں ہو سکا۔ براہ کرم دوبارہ کوشش کریں۔",
  "support.errorRateLimit": "آپ نے آج کئی رپورٹیں بھیجی ہیں — شکریہ۔ براہ کرم مزید بھیجنے کے لیے کل تک انتظار کریں، تاکہ ہر رپورٹ کو صحیح طریقے سے پڑھا جا سکے۔",
  "support.errorTooLong": "یہ اس سے لمبا ہے جو ایک رپورٹ رکھ سکتی ہے — براہ کرم اسے تھوڑا مختصر کریں اور دوبارہ بھیجیں۔",
  "support.errorTooShort": "براہ کرم ہمیں تھوڑا اور بتائیں — ایک یا دو جملے اسے تلاش کرنے میں ہماری مدد کرتے ہیں۔",
  "support.messageLabel": "کیا ہوا؟",
  "support.messagePlaceholder": "ہمیں اپنے الفاظ میں بتائیں کہ آپ کیا کر رہے تھے اور کیا غلط ہوا…",
  "support.sendAnother": "ایک اور رپورٹ بھیجیں",
  "support.sending": "بھیجا جا رہا ہے…",
  "support.sentBody": "ہم ہر رپورٹ پڑھتے ہیں۔ اگر ہمیں مزید تفصیل چاہیے ہو تو ہم آپ کے اکاؤنٹ ای میل پر لکھیں گے۔",
  "support.sentTitle": "شکریہ — آپ کی رپورٹ بھیج دی گئی۔",
  "support.submit": "رپورٹ بھیجیں",
  "support.title": "ایک مسئلہ رپورٹ کریں",
  "support.urgentNote": "اس کے بجائے اپنے اکاؤنٹ سے لاک آؤٹ ہیں؟ آپ کی اضافی چابیاں آپ کو واپس اندر لا سکتی ہیں — اوپر سیکیورٹی اور اضافی چابیاں دیکھیں، یا سائن ان صفحے پر بازیابی دروازہ استعمال کریں۔",
  "training.lessons.mgr-report-problem.step1": "آپ کی ٹیم ٹل پر کام کرتی ہے، جہاں مسائل سب سے پہلے ظاہر ہوتے ہیں۔ اگر ایپ آپ کی ٹیم میں کسی کے لیے خراب ہو یا عجیب برتاؤ کرے تو اسے اسی لمحے رپورٹ کیا جا سکتا ہے — ان کے ذریعے یا آپ کے ذریعے — سیٹنگز سے، مسئلہ رپورٹ کریں کے تحت۔",
  "training.lessons.mgr-report-problem.step2": "سادہ کہانی مانگیں: وہ کیا کر رہے تھے، انہیں کیا توقع تھی، اور اس کے بجائے کیا ہوا۔ اس کا ایک یا دو جملے بعد میں لکھی گئی کامل تفصیل سے زیادہ قیمتی ہیں۔",
  "training.lessons.mgr-report-problem.step3": "رپورٹ خود ہی صفحہ، اسٹور، بھیجنے والے کا کردار، پلان، ایپ زبان اور آلے کی قسم منسلک کرتی ہے؛ پروڈکٹس، اسٹاک اور فروخت کبھی منسلک نہیں ہوتیں۔ اسٹور کے اعداد کے بارے میں کچھ بھی رپورٹ کے ساتھ نہیں جاتا۔",
  "training.lessons.mgr-report-problem.step4": "رپورٹیں ایپ کے پیچھے ٹیم کے پاس جاتی ہیں اور ہر ایک پڑھی جاتی ہے۔ اگر مسئلہ کسی کو اس کے اکاؤنٹ سے لاک آؤٹ کر دے تو رپورٹ کا انتظار نہ کریں: اضافی چابیاں اور سائن ان صفحے کا بازیابی دروازہ انہیں واپس اندر لاتے ہیں۔",
  "training.lessons.mgr-report-problem.title": "جب آپ کی ٹیم کو رکاوٹ آئے: اسے رپورٹ کریں، اس کے گرد کام نہ کریں",
  "training.lessons.owner-report-problem.step1": "آپ کی سبسکرپشن میں ان لوگوں تک براہ راست لائن شامل ہے جو اس ایپ کو بناتے ہیں۔ سیٹنگز کھولیں اور مسئلہ رپورٹ کریں استعمال کریں — یہ ہر پلان پر ہے، آپ کے لیے اور آپ کی ٹیم کے ہر ممبر کے لیے۔",
  "training.lessons.owner-report-problem.step2": "اپنے الفاظ میں کہیں کہ کیا ہوا: آپ کیا کرنے کی کوشش کر رہے تھے، اور ایپ نے اس کے بجائے کیا کیا۔ فارم خود ہی درست کرنے کی تفصیلات — صفحہ، کاروبار، کردار، پلان، زبان اور آلہ — منسلک کرتا ہے؛ آپ کی پروڈکٹس، اسٹاک اور فروخت کبھی شامل نہیں ہوتیں۔",
  "training.lessons.owner-report-problem.step3": "ہر رپورٹ محفوظ ہوتی ہے اور ٹیم اسے پڑھتی ہے۔ اگر مزید تفصیل مدد کرے تو وہ اس شخص کے اکاؤنٹ ای میل پر جواب دیتے ہیں جس نے اسے بھیجا تھا — اس لیے جواب اس شخص تک پہنچتا ہے جس نے مسئلہ دیکھا تھا۔",
  "training.lessons.owner-report-problem.step4": "ایک استثنا: اگر آپ یا کوئی ٹیم ممبر اکاؤنٹ میں بالکل داخل نہیں ہو سکتا تو رپورٹ تیز ترین دروازہ نہیں ہے۔ اضافی چابیاں (سیٹنگز، سیکیورٹی اور اضافی چابیاں) اور سائن ان صفحے پر بازیابی دروازہ بالکل اسی کے لیے موجود ہیں۔",
  "training.lessons.owner-report-problem.title": "ایک مسئلہ رپورٹ کریں: ایپ ٹیم تک آپ کی براہ راست لائن",
  "training.lessons.report-problem.step1": "اگر ایپ میں کچھ خراب ہو، غلط لگے، یا بس عجیب محسوس ہو تو آپ کو اس کے ساتھ جینا نہیں پڑتا۔ سیٹنگز کھولیں اور مسئلہ رپورٹ کریں تلاش کریں — یہ ہر کسی کے لیے، ہر پلان پر موجود ہے۔",
  "training.lessons.report-problem.step2": "منتخب کریں کہ آپ کا نوٹ کس بارے میں ہے — کچھ خراب ہے، کچھ غلط لگتا ہے، ایک خیال، یا کچھ اور — پھر اپنے الفاظ میں لکھیں کہ کیا ہوا۔ اس وقت آپ کیا کر رہے تھے یہ سب سے زیادہ مدد کرتا ہے۔",
  "training.lessons.report-problem.step3": "آپ کا نوٹ خود ہی وہ صفحہ لے جاتا ہے جس پر آپ تھے، آپ کا اسٹور اور کردار، آپ کا پلان، آپ کی ایپ زبان، اور آپ کس قسم کا فون یا براؤزر استعمال کرتے ہیں — وہ تفصیلات جو مسئلہ تلاش کرنے میں مدد کرتی ہیں۔ یہ آپ کی پروڈکٹس، اسٹاک یا فروخت کبھی نہیں لے جاتا۔",
  "training.lessons.report-problem.step4": "اسے بھیجیں، اور یہ سیدھا ایپ کے پیچھے ٹیم کے پاس جاتا ہے، جو ہر رپورٹ پڑھتے ہیں۔ اگر انہیں مزید تفصیل چاہیے ہو تو وہ آپ کے اکاؤنٹ ای میل پر لکھیں گے۔ اس کے بجائے اپنے اکاؤنٹ سے لاک آؤٹ ہیں؟ اپنی اضافی چابیاں یا سائن ان صفحے پر بازیابی دروازہ استعمال کریں — وہ رپورٹ سے تیز ہیں۔",
  "training.lessons.report-problem.title": "ایک مسئلہ رپورٹ کریں: جب کچھ خراب ہو تو ہمیں بتائیں",
