  "training.lessons.owner-move-stock.step1": "درخواستیں مانگنے کے لیے ہوتی ہیں؛ منتقل کرنا مالکان کا کام ہے۔ کراس اسٹور ان باکس صفحے پر اسٹاک منتقل کریں پینل آپ کو — مالک کو — اس اسٹور سے اپنے کسی دوسرے اسٹور میں بغیر درخواست اور بغیر انتظار کے اسٹاک براہِ راست بھیجنے دیتا ہے۔",
  "training.lessons.owner-move-stock.step2": "پروڈکٹ، وہ مقام جہاں سے وہ جائے گا، اور مقدار منتخب کریں۔ ایپ دکھاتی ہے کہ اس مقام پر کتنا موجود ہے، اور کوئی منتقلی اس سے زیادہ کبھی نہیں لے سکتی۔",
  "training.lessons.owner-move-stock.step3": "وہ اسٹور منتخب کریں جہاں وہ جائے گا، اور چاہیں تو وہاں کا ٹھیک مقام بھی۔ اگر اس اسٹور میں پہلے سے وہی SKU ہو، تو اسٹاک اس پروڈکٹ میں شامل ہو جاتا ہے؛ اگر نہ ہو، تو پروڈکٹ اسٹاک سمیت کاپی ہو جاتی ہے۔",
  "training.lessons.owner-move-stock.step4": "دونوں اسٹور ریکارڈ رکھتے ہیں: یہ اسٹور باہر جانے والی منتقلی دکھاتا ہے، دوسرا وصولی دکھاتا ہے۔ اگر منتقلی نہ ہو سکے — کافی موجود نہ ہو، یا دوسرا اسٹور آپ کا نہ ہو — تو کچھ نہیں ہلتا اور ایپ وجہ بتاتی ہے۔",
