  "training.lessons.mgr-pricing.step1": "Business پر، پروڈکٹ فارم میں فروخت قیمت کا سیکشن ہوتا ہے۔ کلیئرنس ایک مستقل کمی ہے — مقرر کریں اور یہ رہتی ہے۔ رول بیک تاریخوں والی سیل ہے: رول بیک قیمت، شروع ہونے کا دن اور ختم ہونے کا دن مقرر کریں۔",
  "training.lessons.mgr-pricing.step2": "آپ کو عام قیمت کبھی دوبارہ نہیں لکھنی پڑتی: یہ پروڈکٹ پر رہتی ہے اور پروڈکٹ فہرست اور اسکینر میں فروخت قیمت کے ساتھ دکھتی ہے، تاکہ کوئی بھی دیکھ سکے کہ چیز عام طور پر کتنے کی ہے۔",
  "training.lessons.mgr-pricing.step3": "جب رول بیک شروع ہو تو تازہ قیمت لیبل چھاپیں — لیبل اس قیمت کو چھاپتے ہیں جو گاہک اس دن ادا کرتا ہے۔ جب اختتامی تاریخ گزر جائے تو قیمت خود بخود عام پر واپس آ جاتی ہے؛ جب آپ شیلف تازہ کریں تو عام لیبل دوبارہ چھاپیں۔",
  "training.lessons.mgr-pricing.step4": "اگر فروخت قیمت کا سیکشن بند دکھے، تو کاروبار Business پلان پر نہیں ہے — فروخت قیمت اسی پلان کی ہے، اور پلان تبدیل کرنے والے مالک ہوتے ہیں۔",
  "training.lessons.mgr-pricing.title": "سیل چلانا: کلیئرنس اور رول بیک",
  "training.lessons.owner-pricing.step1": "پروڈکٹ فارم میں، فروخت قیمت کے تحت، دو طرح کی کمی رہتی ہے۔ کلیئرنس مستقل ہے: کلیئرنس قیمت مقرر کریں اور یہ اس وقت تک کم رہتی ہے جب تک آپ اسے واپس نہ بدلیں۔ رول بیک ایک عارضی سیل ہے — آغاز اور اختتام کی تاریخ کے ساتھ ایک کم قیمت، جیسی سیل آپ بڑے اسٹوروں سے پہلے ہی جانتے ہیں۔",
  "training.lessons.owner-pricing.step2": "عام قیمت کبھی مٹائی نہیں جاتی۔ جب رول بیک چلتا ہے، ایپ فروخت قیمت کے ساتھ عام قیمت ساتھ دکھاتی ہے، اور چھپے ہوئے لیبل فروخت قیمت لے جاتے ہیں، تاکہ شیلف اور کیش میل کھائیں۔",
  "training.lessons.owner-pricing.step3": "جب اختتامی تاریخ گزر جائے تو قیمت خود بخود عام پر واپس آ جاتی ہے — کچھ یاد نہیں رکھنا، کچھ واپس نہیں کرنا۔ جو رول بیک ابھی شروع نہیں ہوا، وہ پروڈکٹ فہرست پر ہی اپنی آغاز تاریخ بتاتا ہے۔",
  "training.lessons.owner-pricing.step4": "فروخت قیمت Business پلان کی خصوصیت ہے۔ Essentials پر فیلڈ بند رہتی ہیں، اور اگر کوئی کاروبار Essentials پر جا کر واپس آئے، تو اس کی کلیئرنس اور رول بیک سیٹنگ وہیں رہتی ہیں، بالکل جیسی چھوڑی گئی تھیں۔",
