  "print.style.previewText": "تیز بھوری لومڑی سست کتے کے اوپر سے چھلانگ لگاتی ہے۔ 1234567890",
  "training.lessons.owner-shipping-labels.step1": "پرنٹ سینٹر میں دونوں پلانز میں شپنگ لیبل انداز موجود ہے: صارف کا آرڈر منتخب کریں اور خریدار کے نام اور پتے اور بھیجنے والے کے طور پر اپنے کاروبار کے ساتھ 4×6 لیبل چھاپیں۔",
  "training.lessons.owner-shipping-labels.step2": "یہ لیبل ہر صارف دستاویز کی طرح وائٹ لیبل ہے: اس پر صرف آپ کے کاروبار کا نام ہوتا ہے — اس ایپ کا نام کبھی نہیں — تاکہ آپ کی دکان سے آیا پارسل آپ ہی کی دکان سے آیا لگے۔",
  "training.lessons.owner-shipping-labels.step3": "گاہک کا پتہ ان کے آخری آرڈر کے بعد 90 دن تک ان کے آرڈرز کے ساتھ رکھا جاتا ہے، اور لیبل جب آرڈر کا محفوظ پتہ ہوتا ہے تو اس سے شروع ہوتا ہے؛ ایک بار کے لیبل کے لیے پرنٹ کے وقت لکھا گیا پتہ واپس محفوظ نہیں کیا جاتا۔ نام پھر بھی آرڈر سے بھرا جاتا ہے تاکہ لیبل کاغذات سے ملے۔",
  "training.lessons.owner-shipping-labels.step4": "یہ لیبل ہر لیبل والے انہی چار کنکشنز سے چھپتا ہے — بلوٹوتھ، وائی فائی، ایتھرنیٹ اور USB — اور 4×6 تھرمل پرنٹر اس کا معیاری سائز ہے۔",
  "training.lessons.owner-shipping-labels.step5": "اس کے بجائے ڈاک خرچ کیریئر سے خریدا؟ اسی سیکشن میں آپ کیریئر کی لیبل فائل — PDF، PNG یا JPG — اپ لوڈ کر سکتے ہیں اور یہ آرڈر پر ہمیشہ محفوظ رہتی ہے: آپ کا ریکارڈ، اگر کچھ ہو جائے تو ہاتھ میں۔ یہ اپنے اصل 4×6 سائز میں پرنٹ ہوتی ہے۔ ایپ کبھی ڈاک خرچ نہیں بیچتی، لہٰذا کیریئر کی قیمت ہی واحد قیمت ہے — اور ہمیشہ درست قیمت۔",
  "training.lessons.owner-shipping-labels.title": "صارف کے آرڈرز کے لیے شپنگ لیبل",
  "training.lessons.print-shipping-label.step1": "جب کوئی آرڈر بھیجنے کے لیے تیار ہو تو پرنٹ سینٹر کھولیں، شپنگ لیبل انداز منتخب کریں اور پھر صارف کا آرڈر منتخب کریں۔ خریدار کا نام آرڈر سے بھر جاتا ہے۔",
  "training.lessons.print-shipping-label.step2": "وہ پتہ جانچیں جہاں پارسل جا رہا ہے۔ جب آرڈر میں گاہک کا پتہ ہوتا ہے — ان کے آخری آرڈر کے بعد 90 دن تک رکھا گیا — تو یہ آپ کے لیے بھر جاتا ہے؛ پرنٹ کے وقت آپ جو پتہ لکھتے ہیں وہ واپس محفوظ نہیں ہوتا، اس لیے پرنٹ کرنے سے پہلے پوسٹ کوڈ اور آخری لائن احتیاط سے جانچیں۔",
  "training.lessons.print-shipping-label.step3": "آپ کے کاروبار کا نام بھیجنے والے کے طور پر اوپر چھپتا ہے۔ اگر آپ چاہتے ہیں کہ آپ کا پتہ بھی لیبل پر ہو تو اسے بھیجنے والے کے پتے والے خانے میں لکھیں؛ اگر ظاہر نہ کرنا چاہیں تو خالی چھوڑ دیں۔",
  "training.lessons.print-shipping-label.step4": "4×6 لیبل پر چھاپیں — تھرمل لیبل پرنٹر عام طور پر موزوں ہوتا ہے — یا براؤزر کے پرنٹ بٹن سے کسی بھی پرنٹر پر۔ لیبل کو پارسل پر ہموار چپکائیں، جہاں وہ کنارے پر نہ مڑے۔",
  "training.lessons.print-shipping-label.step5": "اگر ڈاک خرچ کیریئر سے خریدا گیا تھا، تو اس کے بجائے ان کی لیبل فائل آرڈر پر محفوظ کریں: آپ کی کیریئر کا لیبل سیکشن میں کیریئر کی دی ہوئی PDF، PNG یا JPG اپ لوڈ کریں۔ یہ آپ کے ریکارڈ کے طور پر آرڈر پر رہتی ہے اور اپنے اصل 4×6 سائز میں پرنٹ ہوتی ہے — اور جب آپ اسے استعمال کرنا چاہیں تو ایپ کا اپنا ایڈریس لیبل ہمیشہ وہاں موجود ہے۔",
  "training.lessons.print-shipping-label.title": "شپنگ لیبل چھاپیں",
