  "apiErrors.code.staffOutsideWindow": "ایپ آپ کی مقررہ شفٹ سے تقریباً 10 منٹ پہلے کھلتی ہے، اور ابھی آپ کی شفٹ کا وقت نہیں ہوا۔",
