  "apiErrors.subscriptionRequired": "اس ورک اسپیس کی کوئی فعال سبسکرپشن نہیں ہے۔ اسے استعمال کرنے کے لیے کسی پلان کی سبسکرپشن لیں — رسائی صرف اس وقت شروع ہوتی ہے جب آزمائش یا ادائیگی کی تصدیق ہو جائے۔",
