  "workforce.autoLogoutNote": "آپ کے پاس اپنے اوقات چیک کرنے کے لیے تقریباً 10 منٹ ہیں — پھر ایپ آپ کی اگلی مقررہ شفٹ تک آپ کو لاگ آؤٹ کر دیتی ہے۔",
  "settings.install.title": "ایپ ڈاؤن لوڈ کریں",
