  "settings.install.manualIntro": "اس وقت کوئی انسٹال پرامپٹ دستیاب نہیں ہے۔ آپ پھر بھی ایپ کو ہاتھ سے شامل کر سکتے ہیں:",
  "settings.install.iosSteps": "Safari میں، شیئر بٹن دبائیں، پھر «ہوم اسکرین پر شامل کریں» دبائیں، پھر «شامل کریں»۔ ایپ کسی بھی دوسری ایپ کی طرح آپ کی ہوم اسکرین پر ہوگی۔",
  "settings.install.androidSteps": "اپنے براؤزر میں، مینیو (تین نقطے) دبائیں، پھر «ایپ انسٹال کریں» یا «ہوم اسکرین پر شامل کریں» دبائیں، اور تصدیق کریں۔ ایپ کسی بھی دوسری ایپ کی طرح آپ کی ہوم اسکرین پر ہوگی۔",
  "settings.install.desktopSteps": "اپنے براؤزر کے ایڈریس بار میں، اگر انسٹال آئیکن دکھائی دے تو اس پر کلک کریں۔ اگر کوئی آئیکن نہ ہو تو براؤزر مینیو کھولیں اور «Luminous StockHaven انسٹال کریں» یا «ڈیسک ٹاپ پر شامل کریں» منتخب کریں۔",
  "staffWelcome.title": "Luminous StockHaven میں خوش آمدید",
