  "staffWelcome.defaultGladLine": "ہمیں خوشی ہے کہ آپ یہاں ہیں۔",
  "staffWelcome.start": "میری تربیت شروع کریں",
  "staffWelcome.skip": "ابھی چھوڑ دیں",
  "staffWelcome.editor.title": "نئے عملے کے لیے خوش آمدیدی پیغام",
  "staffWelcome.editor.description": "وہ الفاظ جو ایک نیا شخص ایک بار، اپنے پہلے سائن ان پر، ہر چیز سے پہلے پڑھتا ہے۔ انہیں اپنے الفاظ میں لکھیں تاکہ یہ آپ کی دکان جیسا محسوس ہو۔",
  "staffWelcome.editor.permanentNote": "یہ پہلی سطر خود ایپ ہے — یہ ہمیشہ دکھائی دیتی ہے اور اسے نہ بدلا جا سکتا ہے نہ ہٹایا جا سکتا ہے۔",
  "staffWelcome.editor.tokens": "{name} وہاں لکھیں جہاں شخص کا پہلا نام آنا چاہیے، اور {store} وہاں جہاں آپ کی دکان کا نام آنا چاہیے — ایپ ہر شخص کے لیے انہیں بھر دیتی ہے۔",
  "staffWelcome.editor.emptyNote": "خانہ خالی چھوڑ دیں تاکہ ایپ کا معیاری خوش آمدید استعمال ہو (جو خانے میں ہلکا سا دکھائی دیتا ہے)۔ نیا شخص کبھی خالی صفحہ نہیں دیکھتا۔",
  "staffWelcome.editor.save": "خوش آمدیدی پیغام محفوظ کریں",
  "staffWelcome.editor.saved": "خوش آمدیدی پیغام محفوظ ہو گیا۔",
  "training.lessons.staff-shift-windows.title": "آپ کا سائن ان آپ کی شفٹ کے پیچھے چلتا ہے",
  "training.lessons.staff-shift-windows.step1": "آپ اپنی مقررہ شفٹ شروع ہونے سے تقریباً 10 منٹ پہلے سے سائن ان کر سکتے ہیں۔ اس سے پہلے ایپ بند رہتی ہے — سائن ان صفحہ آپ کو بتائے گا کہ آپ کی اگلی شفٹ کب شروع ہوتی ہے۔",
  "training.lessons.staff-shift-windows.step2": "جیسے ہی آپ کلاک آؤٹ کرتے ہیں، آپ کے پاس اپنا صفحہ چیک کرنے کے لیے 10 منٹ ہوتے ہیں، کیونکہ آپ کی اگلی مقررہ تاریخ تک آپ کو لاگ آؤٹ کر دیا جائے گا۔",
  "training.lessons.staff-shift-windows.step3": "اگر آپ ان 10 منٹوں کے اندر دوبارہ کلاک ان کر لیں تو لاگ آؤٹ منسوخ ہو جاتا ہے اور آپ سائن ان رہتے ہیں۔",
  "training.lessons.staff-shift-windows.step4": "شیڈول میں شفٹ نہ ہو تو اس دن سائن ان نہیں ہو سکتا۔ اگر آپ سمجھتے ہیں کہ آپ کو شیڈول میں ہونا چاہیے تو اپنے مینیجر یا مالک سے پوچھیں — وہی شیڈول شائع کرتے ہیں جو آپ کا دروازہ کھولتا ہے۔",
  "training.lessons.manager-shift-windows.title": "شیڈول شائع کرنا رسائی کھولتا اور بند کرتا ہے",
  "training.lessons.manager-shift-windows.step1": "جو شیڈول آپ اپنی ٹیم کے لیے شائع کرتے ہیں وہ شفٹوں کی فہرست سے بڑھ کر ہے: یہی ہر شخص کی ایپ تک رسائی کھولتا اور بند کرتا ہے۔ ٹیم کا رکن اس شفٹ سے تقریباً 10 منٹ پہلے سائن ان کر سکتا ہے جو آپ نے اس کے لیے شائع کی — اس سے پہلے نہیں۔",
  "training.lessons.manager-shift-windows.step2": "جب وہ کلاک آؤٹ کرتا ہے تو اس کے پاس اپنے اوقات چیک کرنے کے لیے تقریباً 10 منٹ ہوتے ہیں، پھر ایپ اس کی اگلی مقررہ شفٹ تک اسے لاگ آؤٹ کر دیتی ہے۔ اس دن کوئی شائع شدہ شفٹ نہ ہو تو وہ اس دن سائن ان نہیں کر سکتا۔",
  "training.lessons.manager-shift-windows.step3": "شفٹیں احتیاط سے شائع کریں: غائب یا غلط شفٹ کسی شخص کو صرف شیڈول سے نہیں، ایپ سے بھی باہر بند کر دیتی ہے۔ اگر کوئی کہے کہ وہ اندر نہیں آ سکتا تو پہلے اس کا شیڈول چیک کریں۔",
  "training.lessons.manager-shift-windows.step4": "آپ کی اپنی رسائی بھی اسی طرح کام کرتی ہے، ایک درجہ اوپر: جو شیڈول مالک آپ کے لیے شائع کرتا ہے وہ آپ کی ونڈو آپ کی شفٹ سے تقریباً 10 منٹ پہلے کھولتا ہے، اور آپ کے کلاک آؤٹ کے تقریباً 10 منٹ بعد آپ کا سیشن بند ہو جاتا ہے۔",
  "training.lessons.owner-shift-windows.title": "شفٹ ونڈوز: شیڈول رسائی کھولتا اور بند کرتا ہے",
  "training.lessons.owner-shift-windows.step1": "رسائی اس شیڈول کے پیچھے چلتی ہے جو آپ شائع کرتے ہیں۔ عملے کا رکن یا مینیجر اپنی مقررہ شفٹ سے تقریباً 10 منٹ پہلے سائن ان کر سکتا ہے — اس سے پہلے نہیں۔ شفٹ سے باہر ایپ ان کے لیے بند رہتی ہے، تاکہ دکان کی معلومات ڈیوٹی پر موجود لوگوں کے پاس رہیں۔",
  "training.lessons.owner-shift-windows.step2": "جب وہ کلاک آؤٹ کرتے ہیں تو ان کے پاس اپنے اوقات چیک کرنے کے لیے تقریباً 10 منٹ ہوتے ہیں، پھر ایپ خود ہی ان کی اگلی مقررہ شفٹ تک انہیں لاگ آؤٹ کر دیتی ہے۔ ان 10 منٹوں کے اندر دوبارہ کلاک ان کرنا لاگ آؤٹ منسوخ کر دیتا ہے۔",
  "training.lessons.owner-shift-windows.step3": "اس دن کوئی شائع شدہ شفٹ نہ ہو تو اس دن کوئی ونڈو نہیں: جو شخص شیڈول میں نہیں وہ سائن ان نہیں کر سکتا۔ شیڈول ورک فورس میں شائع کریں، اس کا دروازہ اسی کے ساتھ کھل جائے گا۔",
  "training.lessons.owner-shift-windows.step4": "آپ واحد استثنا ہیں: مالک کو کوئی شیڈول نہیں کرتا، اس لیے آپ کے سائن ان کی کبھی کوئی ونڈو نہیں ہوتی۔ مینیجر اس شیڈول سے محدود ہوتا ہے جو آپ اس کے لیے شائع کرتے ہیں، اسی طرح جیسے عملہ ان کے لیے شائع شدہ شیڈول سے محدود ہوتا ہے۔",
  "settings.install.ownerNote": "اگر آپ کا ایپ اسٹور کبھی آپ کو ایپ استعمال کرنے سے روکے، تو یہ لنک آپ کو ایپ براہ راست اسی ویب سائٹ سے دیتا ہے — اسٹور کی ضرورت نہیں۔",
  "layout.signOutLink": "لاگ آؤٹ",
