  "subscribe.memberOpenApp": "ایپ کھولیں",
  "apiErrors.planLimitNeutral": "یہ ابھی شامل نہیں کیا جا سکتا — کاروبار کے مالک سے پوچھیں۔",
  "training.lessons.owner-confidentiality.title": "آپ کی معلومات خفیہ رہتی ہیں",
  "training.lessons.owner-confidentiality.step1": "Luminous StockHaven آپ کی معلومات کو آپ کے عملے سے خفیہ رکھتا ہے۔ آپ کی ادائیگیاں، آپ کی آزمائش، آپ کی رکنیت اور آپ کی بلنگ کی حالت — اور آپ کی ذاتی معلومات کے بارے میں کچھ بھی — صرف آپ کی ہے: عملہ اور منیجر انہیں کبھی نہیں دیکھتے، ایپ میں کہیں بھی نہیں۔",
  "training.lessons.owner-confidentiality.step2": "اس میں خاموش جگہیں بھی شامل ہیں: ان کے صفحات پر آزمائش کی الٹی گنتی نہیں، ان کی ترتیبات میں منصوبہ یا بلنگ کا کوئی سیکشن نہیں، ادائیگی کی کوئی وارننگ نہیں۔ ان کی ترتیبات ذاتی ہیں — ان کا اپنا اکاؤنٹ، سیکیورٹی، ظاہری شکل اور زبان — علاوہ صرف وہ اضافی سیکشن جو آپ ان کے لیے منتخب کریں۔ بلنگ کبھی بھی نشانات میں سے نہیں ہے۔",
  "training.lessons.owner-confidentiality.step3": "اگر اکاؤنٹ کبھی بلنگ کی وجہ سے رک جائے، تو آپ کے عملے کو کبھی نہیں بتایا جائے گا کہ کیوں۔ وہ صرف ایک سادہ، غیر جانبدار روک دیکھتے ہیں — تبدیلیاں ابھی بند ہیں — تاکہ آپ اپنی ٹیم کو اپنے الفاظ میں سمجھا سکیں۔",
  "training.lessons.owner-confidentiality.step4": "اور اگر آپ کبھی کچھ ایسا دیکھیں جو آپ کے عملے کو دکھایا جا رہا ہو اور نہیں دکھایا جانا چاہیے — کوئی بھی لیک — ترتیبات کھولیں اور مسئلہ رپورٹ کریں پر ٹیپ کر کے ہمیں بتائیں، تاکہ ہم اسے جلد از جلد ٹھیک کر سکیں۔",
  "staffLib.perm.settingsContactDetails": "کاروباری رابطے کی تفصیلات (پتہ اور فون)",
