  "apiErrors.notFound.voiceNoteFound": "صوتی نوٹ نہیں ملا۔",
  "apiErrors.invalidValue.sendVoiceRecording": "زیادہ سے زیادہ چند منٹ کی صوتی ریکارڈنگ بھیجیں۔",
  "apiErrors.invalidValue.recordingNotPrepared": "وہ ریکارڈنگ تیار نہیں ہو سکی — براہ کرم دوبارہ ریکارڈ کریں۔",
  "training.lessons.messages-private.step5": "آپ صوتی نوٹ بھی بھیج سکتے ہیں: پیغام خانے کے پاس مائیکروفون کو چھوئیں، بولیں، اور روکیں کو چھوئیں۔ پہلے اسے سنیں — پھر بھیجیں، یا حذف کر کے دوبارہ ریکارڈ کریں۔ جب کوئی آپ کو بھیجے تو ان کی اصل آواز سننے کے لیے چلائیں کو چھوئیں۔",
  "training.lessons.owner-messages-oversight.step5": "پڑھنے کے نشانات: جب ٹیم کا کوئی رکن آپ کا بھیجا ہوا پیغام پڑھتا ہے، تو آپ اسے پڑھا ہوا نشان زدہ دیکھتے ہیں۔ عملہ اور منیجر ایک دوسرے کے پڑھنے کے نشانات اسی طرح دیکھتے ہیں، دونوں طرف۔",
  "training.lessons.owner-messages-oversight.step6": "آپ کا اپنا پڑھنا نظر نہیں آتا۔ جب آپ عملے کے کسی رکن کا بھیجا ہوا پیغام پڑھتے ہیں، تو وہ کبھی پڑھنے کا نشان نہیں دیکھتا — اور آپ کو اپنی ٹیم کو یہ بتانے کی ضرورت نہیں کہ ان کی گفتگو ایپ میں محفوظ ہوتی ہے اور آپ، مالک، انہیں پڑھ سکتے ہیں۔ یہ نگرانی آپ کی دکان کی دیکھ بھال کا حصہ ہے۔",
  "training.lessons.owner-messages-oversight.step7": "عملے کے ارکان کے درمیان منفی پیغامات کے بارے میں آپ کیا کرتے ہیں، یہ آپ پر ہے۔ اسے گزر جانے دیں، کسی سے خاموشی سے بات کریں، یا کارروائی کریں — انتخاب آپ کا ہے، اور آپ کو کبھی یہ بتانے کی ضرورت نہیں کہ آپ نے یہ کہاں دیکھا۔",
