  "training.lessons.owner-store-policies.title": "آپ کے اسٹور کی پالیسیاں اور شرائط",
  "training.lessons.owner-store-policies.step1": "ترتیبات کھولیں اور اسٹور کی پالیسیاں و شرائط والا کارڈ تلاش کریں۔ اس میں دو دستاویزات ہیں: آپ کے اسٹور کی پالیسیاں — آپ کے اسٹور کے گھریلو اصول — اور آپ کی شرائط و ضوابط۔",
  "training.lessons.owner-store-policies.step2": "ہر دستاویز وہیں لکھی جا سکتی ہے، یا فائل کے طور پر اپ لوڈ کی جا سکتی ہے (PDF، متن، Word یا OpenDocument، 2 MB تک)۔ ایک یا دوسری: متن محفوظ کرنا فائل کی جگہ لے لیتا ہے، اور فائل اپ لوڈ کرنا متن کی جگہ لے لیتا ہے۔ دستاویز ہٹانے سے وہ صاف ہو جاتی ہے۔",
  "training.lessons.owner-store-policies.step3": "آپ کی ٹیم دونوں دستاویزات ایک بار دیکھتی ہے، پہلی شروعات پر اپنے خوش آمدید صفحے پر، اور انہیں کسی بھی وقت اپنی ترتیبات میں پڑھ سکتی ہے۔ آپ کی ٹیم کے لیے وہ صرف پڑھنے کے لیے ہیں — صرف آپ انہیں لکھ یا بدل سکتے ہیں۔",
  "training.lessons.owner-store-policies.step4": "ہر کاروبار اپنی دستاویزات خود رکھتا ہے: جو کچھ آپ یہاں لکھتے ہیں وہ صرف اسی اسٹور کا ہے اور کبھی کسی دوسرے کاروبار میں نظر نہیں آتا۔ Luminous StockHaven کی اپنی شرائط اور پالیسیاں ترتیبات میں آپ کی دستاویزات کے ساتھ رہتی ہیں، اور انہیں بھی سب پڑھ سکتے ہیں۔",
  "training.lessons.welcome-basics.step5": "آپ کے اسٹور کی پالیسیاں اور شرائط آپ کے خوش آمدید صفحے پر ایک بار دکھائی جاتی ہیں، اور وہ ترتیبات میں رہتی ہیں، جہاں آپ انہیں کسی بھی وقت پڑھ سکتے ہیں۔",
