  "staff.memberDialog.lowStockAccessHint": "پہلے نشان کے ساتھ، یہ شخص کم اسٹاک کے انتباہات دیکھتا ہے — «توجہ درکار ہے» والا خانہ، کم اسٹاک والا صفحہ اور کم سطح کے نشانات۔ دوسرے نشان کے ساتھ، وہ کسی پروڈکٹ کا ری آرڈر پوائنٹ تبدیل کر سکتا ہے؛ اس کے بغیر، ری آرڈر پوائنٹ والا خانہ نظر آتا رہے گا، لیکن اس میں تبدیلی محفوظ نہیں ہوگی۔",
  "apiErrors.reorderChangeReserved": "صرف مالک، یا وہ ٹیم رکن جسے مالک نے ری آرڈر پوائنٹس تبدیل کرنے کی اجازت دی ہو، ری آرڈر پوائنٹ تبدیل کر سکتا ہے۔",
  "apiErrors.alertsViewReserved": "صرف مالک، یا وہ ٹیم رکن جسے مالک نے کم اسٹاک کے انتباہات دیکھنے کی اجازت دی ہو، کم اسٹاک کے انتباہات دیکھ سکتا ہے۔",
  "apiErrors.quizRequired": "یہ سبق ایک مختصر کوئز کے ساتھ ختم ہوتا ہے — سبق مکمل کرنے کے لیے اس کا درست جواب دیں۔",
  "apiErrors.trainingIncomplete": "ابھی نہیں — اس شخص کی تربیت ابھی مکمل ہونا باقی ہے۔",
