  "settings.policyQuiz.expected": "متوقع جواب",
  "settings.policyQuiz.expectedHint": "آپ کے الفاظ میں وہ جواب جس کی آپ توقع کرتے ہیں۔ تقریباً لفظ بہ لفظ ملتا جواب فوراً درست شمار کیا جاتا ہے؛ باقی آپ کے پاس دیکھنے کے لیے آتے ہیں۔",
  "settings.policyQuiz.hint": "اپنی ٹیم کے لیے اس دستاویز کے بارے میں سوالات لکھیں۔ جب آپ ان کے اسٹاف ریکارڈ میں ان کے لیے یہ تربیت ٹک کرتے ہیں، تو وہ تربیت میں ان کے جوابات دیتے ہیں۔ آپ کتنے سوالات لکھ سکتے ہیں اس کی کوئی حد نہیں ہے۔",
