  "staff.memberDialog.trainingAccessHint": "اسٹور پالیسیاں اور شرائط پڑھنا سب کے لیے ہے۔ یہ ٹک وہ کوئز تربیت تفویض کرتے ہیں جو مالک سیٹنگز میں ہر دستاویز کے ساتھ بناتا ہے۔",
  "staffLib.area.trainingAccess": "پالیسی کوئز تربیت",
  "staffLib.perm.trainingPoliciesQuiz": "اسٹور پالیسیوں کی کوئز تربیت",
