  "training.lessons.your-profile-photo.title": "آپ کی پروفائل تصویر",
  "training.lessons.your-profile-photo.step1": "آپ کی تصویر آپ کے نام کے ساتھ ایپ کے اوپر، عملے کے صفحے پر، اور آپ کے پیغامات کے ساتھ ظاہر ہوتی ہے — جب مالک اس کی منظوری دے دے۔ اس وقت تک صرف آپ کے نام کے ابتدائی حروف دکھائی دیتے ہیں۔",
  "training.lessons.your-profile-photo.step2": "ترتیبات کھولیں اور اپنی پروفائل تصویر تلاش کریں۔ اپنی ایک تصویر منتخب کریں اور اسے بھیجیں۔ یہ منظوری کے لیے مالک کے پاس جاتی ہے — انتظار کے دوران یہ کہیں ظاہر نہیں ہوتی۔",
  "training.lessons.your-profile-photo.step3": "جب مالک اس کی منظوری دیتا ہے تو آپ کی گھنٹی بجتی ہے اور آپ کی تصویر دکھائی دینا شروع ہو جاتی ہے۔ اگر یہ منظور نہ ہو تو کوئی دوسری تصویر منتخب کریں اور اس کے بجائے وہ بھیجیں۔",
  "training.lessons.your-profile-photo.step4": "اپنی تصویر تبدیل کرنا بھی اسی طرح کام کرتا ہے: نئی تصویر منظوری کی منتظر رہتی ہے، اور آپ کی موجودہ تصویر اس وقت تک اپنی جگہ برقرار رہتی ہے جب تک نئی منظور نہ ہو جائے۔ اگر کوئی تبدیلی منظور نہ ہو تو آپ اپنی دوسری تصویر برقرار رکھتے ہیں۔",
  "training.lessons.owner-profile-photos.title": "پروفائل تصاویر اور آپ کا نام",
  "training.lessons.owner-profile-photos.step1": "ہر شخص کی تصویر اس کے نام کے ساتھ ایپ کے اوپر، آپ کے عملے کے صفحے پر، اور اس کے پیغامات کے ساتھ دکھائی دیتی ہے۔ ٹیم کے رکن کی تصویر اس وقت تک کہیں ظاہر نہیں ہوتی جب تک آپ اس کی منظوری نہ دیں — منظوری صرف آپ کا حق ہے، اور کوئی بھی اپنی تصویر خود منظور نہیں کر سکتا۔",
  "training.lessons.owner-profile-photos.step2": "جب کوئی تصویر بھیجتا ہے تو آپ کی گھنٹی بجتی ہے۔ اسے دیکھنے کے لیے عملے کا صفحہ کھولیں، پھر منظور کریں یا منظور نہ کریں منتخب کریں۔ اگر آپ اس کی منظوری نہیں دیتے تو اس شخص سے کہا جاتا ہے کہ وہ کوئی دوسری تصویر منتخب کرے۔",
  "training.lessons.owner-profile-photos.step3": "اگر کوئی شخص اپنی تصویر تبدیل کرتا ہے تو نئی تصویر اسی طرح آپ کی منظوری کی منتظر رہتی ہے۔ اس کی موجودہ تصویر انتظار کے دوران اپنی جگہ برقرار رہتی ہے — اور اگر آپ تبدیلی کی منظوری نہیں دیتے تو برقرار رہتی ہے۔",
  "training.lessons.owner-profile-photos.step4": "آپ کی اپنی تصویر کو کسی منظوری کی ضرورت نہیں: اسے ترتیبات میں، آپ کی پروفائل تصویر کے تحت مقرر کریں۔ اسی کارڈ میں آپ کا نام بھی ہوتا ہے — جو نام آپ وہاں مقرر کرتے ہیں وہ ہر اس جگہ لفظ مالک کی جگہ لے لیتا ہے جہاں آپ کی ٹیم اسے دیکھتی ہے، ایپ میں اور پیغامات میں۔",
