  "training.lessons.mgr-clock-callin.step3": "ونڈو اس وقت تک کھلی رہتی ہے جب تک وہ شخص کلاک آؤٹ نہ کرے — پھر سائن آؤٹ سے پہلے کی معمول کی 10 منٹ کی مہلت آتی ہے — یا جب تک آپ یا مالک اسے پہلے بند نہ کر دیں۔ کوئی چیز اسے خود نہیں بند کرتی۔",
  "training.lessons.mgr-clock-callin.step4": "جب کوئی کلاک آؤٹ کرنا بھول جائے، تو مقررہ شفٹ ختم ہوتے ہی اس کا ریکارڈ اسٹاف پیج اور پے رول میں نشان زد ہو جاتا ہے، اور آپ کو اور مالک کو اطلاع ملتی ہے۔ ریکارڈ درست ہونے تک گنتا رہتا ہے۔",
  "training.lessons.mgr-clock-callin.step5": "ریکارڈ اسٹاف پیج سے درست کریں: کلاک ان، کلاک آؤٹ اور وقفوں کے اوقات مقرر کریں۔ منتظم صرف عملے کے ریکارڈ درست کرتا ہے — منتظم کے اپنے ریکارڈ مالک درست کرتا ہے۔",
