  "training.lessons.owner-staff-documents.title": "عملے کے دستاویزات",
  "training.lessons.owner-staff-documents.step1": "آپ کی ٹیم کے ہر شخص کی عملے کے صفحے پر ایک دستاویزی فائل ہے۔ وہ کاغذات اپ لوڈ کریں جو آپ اس کے لیے رکھتے ہیں — ایک W-4 فارم، اس کی ملازمت کی درخواست، ٹیکس فارم، اس کی شناختی دستاویز کی نقل — اور انہیں عنوان دیں، یا فائل کا نام برقرار رکھیں۔",
  "training.lessons.owner-staff-documents.step2": "ہر اپ لوڈ محفوظ رہتا ہے۔ نیا نسخہ شامل کرنا پرانے کو کبھی حذف نہیں کرتا — تمام نسخے فہرست میں رہتے ہیں، سب سے نیا پہلے، ہر ایک کی اپنی تاریخ اور اسے اپ لوڈ کرنے والے کا نام۔",
  "training.lessons.owner-staff-documents.step3": "عملے کے دستاویزات صرف آپ دیکھ سکتے ہیں، جب تک کہ آپ کسی منتظم کو اس کے رکنی ریکارڈ میں عملے کے دستاویزات کا نشان نہ دیں۔ یہ نشان بطور ڈیفالٹ بند ہے، اور کوئی کردار اسے نہیں رکھتا۔",
  "training.lessons.owner-staff-documents.step4": "نشان آن ہونے سے پہلے، ایک انتباہ بتاتا ہے کہ اس کا مطلب کیا ہے: یہ شخص آپ کے عملے کے ارکان کے بارے میں خفیہ معلومات دیکھ سکے گا، بشمول سوشل سیکیورٹی نمبر اور تاریخ پیدائش۔ جس شخص کی دستاویز ہو وہ اپنی فائل کبھی نہیں دیکھتا۔",
  "training.lessons.mgr-staff-documents.title": "عملے کے دستاویزات",
  "training.lessons.mgr-staff-documents.step1": "مالک نے آپ پر عملے کے دستاویزات کے نشان کا بھروسا کیا ہے۔ عملے کے صفحے پر، آپ اپنی ٹیم کے عملے کے ارکان کی دستاویزی فائل کھول سکتے ہیں۔",
  "training.lessons.mgr-staff-documents.step2": "ہر فائل ہر نسخہ محفوظ رکھتی ہے: جب آپ نئی نقل شامل کرتے ہیں، پرانی نقلیں اس کے نیچے فہرست میں رہتی ہیں، سب سے نئی پہلے، ہر ایک کی اپنی تاریخ اور اسے اپ لوڈ کرنے والے کا نام۔",
  "training.lessons.mgr-staff-documents.step3": "ان فائلوں میں سوشل سیکیورٹی نمبر، تاریخ پیدائش اور دیگر نجی معلومات ہو سکتی ہیں۔ صرف وہی کھولیں جس کی ضرورت ہو، اور دستاویز کو کاروبار سے باہر کبھی شیئر نہ کریں۔",
  "training.lessons.mgr-staff-documents.step4": "مالک کسی بھی وقت نشان واپس لے سکتا ہے، اور دروازہ فوراً بند ہو جاتا ہے۔ منتظم کے اپنے دستاویزات صرف مالک کے پاس رہتے ہیں۔",
