  "nav.xstoreMessages": "کراس اسٹور پیغامات",
  "plansLib.businessIncludes.xstoreMessages": "کراس اسٹور پیغامات — آپ کی پوری ٹیم، آپ کے ہر کاروبار میں",
  "xstore.title": "کراس اسٹور پیغامات",
  "xstore.help": "اس اکاؤنٹ پر موجود ہر شخص، آپ کے تمام کاروباروں میں، ایک ہی ان باکس میں۔ یہاں ان میں سے کسی کو بھی پیغام بھیجیں — تحریری یا صوتی، ترسیل اور پڑھے جانے کے نشانات کے ساتھ۔ آپ کے اسٹور کے اندر کے پیغامات جیسے ہیں ویسے ہی رہیں گے۔",
