  "xstore.deliveredLabel": "پہنچ گیا",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "کراس اسٹور پیغامات Business پلان کا حصہ ہیں۔",
  "apiErrors.invalidValue.personNotPartAccount": "وہ شخص اس اکاؤنٹ کا حصہ نہیں ہے۔",
  "training.lessons.owner-xstore-messages.title": "مالکان کے لیے — آپ کے اسٹوروں میں پیغامات",
  "training.lessons.owner-xstore-messages.step1": "کراس اسٹور پیغامات ایک دوسرا ان باکس ہے، پیغامات سے الگ۔ پیغامات اس اسٹور کے لیے ہیں جس میں آپ موجود ہیں؛ یہ دروازہ آپ کے اکاؤنٹ پر موجود ہر شخص تک پہنچتا ہے، آپ کی ملکیت کے ہر کاروبار میں — زیادہ سے زیادہ پانچ تک۔",
  "training.lessons.owner-xstore-messages.step2": "مینیو سے کراس اسٹور پیغامات کھولیں اور فہرست میں موجود کسی کے ساتھ بھی گفتگو شروع کریں۔ فہرست میں آپ کے تمام کاروباروں کے ہر ٹیم رکن کو دکھایا جاتا ہے جس نے سائن ان کیا ہے، ان اسٹوروں کے ساتھ جہاں وہ کام کرتے ہیں۔",
  "training.lessons.owner-xstore-messages.step3": "تصاویر بھی ساتھ آتی ہیں: ہر شخص کی منظور شدہ پروفائل تصویر دکھائی جاتی ہے، یا نہ ہونے کی صورت میں ان کے نام کے ابتدائی حروف۔ ہر پیغام پر وہ تاریخ اور وقت ہوتا ہے جب وہ بھیجا گیا تھا۔",
  "training.lessons.owner-xstore-messages.step4": "اپنے پیغامات کے نیچے، پیغام پہنچتے ہی آپ کو پہنچ گیا دکھائی دے گا، اور جب دوسرا شخص گفتگو کھولے گا تو پڑھا گیا دکھائی دے گا۔ صوتی نوٹ یہاں بھی کام کرتے ہیں، بالکل پیغامات کی طرح۔",
  "training.lessons.owner-xstore-messages.step5": "یہاں کی گفتگو ان دو لوگوں کے درمیان نجی رہتی ہے جو اس میں شامل ہیں۔ آپ کے اسٹور کے اندر کے پیغامات پر آپ کی نگرانی اسٹوروں سے آگے نہیں پہنچتی۔",
  "training.lessons.mgr-xstore-messages.title": "منیجرز کے لیے — آپ کے اسٹوروں میں پیغامات",
  "training.lessons.mgr-xstore-messages.step1": "کراس اسٹور پیغامات اس اکاؤنٹ پر موجود ہر شخص تک پہنچتے ہیں، ہر کاروبار میں — صرف اس اسٹور تک نہیں جس میں آپ موجود ہیں۔ یہ مینیو میں ہے، پیغامات سے الگ۔",
  "training.lessons.mgr-xstore-messages.step2": "فہرست سے گفتگو شروع کریں: سائن ان کرنے والا ہر ٹیم رکن وہاں موجود ہے، ان کے نام کے ساتھ وہ اسٹور جہاں وہ کام کرتے ہیں۔",
  "training.lessons.mgr-xstore-messages.step3": "تحریر بھیجیں، یا صوتی نوٹ ریکارڈ کریں۔ صوتی نوٹ بھیجنے سے پہلے آپ اسے سن سکتے ہیں، پھینک سکتے ہیں، یا بھیج سکتے ہیں — بالکل پیغامات کی طرح۔",
  "training.lessons.mgr-xstore-messages.step4": "آپ کے پیغامات پہنچنے پر پہنچ گیا دکھاتے ہیں اور جب دوسرا شخص گفتگو کھولے تو پڑھا گیا دکھاتے ہیں۔ ہر نام کے ساتھ والی تصویر اس شخص کی منظور شدہ پروفائل تصویر ہے۔",
  "training.lessons.staff-xstore-messages.title": "آپ کے اسٹوروں میں پیغامات",
  "training.lessons.staff-xstore-messages.step1": "کراس اسٹور پیغامات وہ جگہ ہے جہاں آپ اس اکاؤنٹ پر موجود کسی سے بھی رابطہ کر سکتے ہیں، مالک کے کسی بھی کاروبار میں — دوسرے اسٹور کے لیے سوال کو اب انتظار نہیں کرنا پڑے گا۔",
  "training.lessons.staff-xstore-messages.step2": "اسے مینیو سے کھولیں، شخص منتخب کریں، اور لکھیں۔ اگر آپ کو درکار شخص فہرست میں نہیں ہے، تو انہوں نے ابھی تک سائن ان نہیں کیا ہے — جیسے ہی وہ کریں گے، وہ ظاہر ہو جائیں گے۔",
  "training.lessons.staff-xstore-messages.step3": "آپ یہاں صوتی نوٹ بھی بھیج سکتے ہیں: ریکارڈ کریں، سن کر دیکھیں، پھر بھیجیں یا پھینک دیں۔ ہر پیغام وہ تاریخ اور وقت دکھاتا ہے جب وہ بھیجا گیا تھا۔",
  "training.lessons.staff-xstore-messages.step4": "جب آپ پیغام بھیجتے ہیں تو پہنچتے ہی وہ پہنچ گیا دکھاتا ہے، اور جب دوسرا شخص گفتگو کھولے تو پڑھا گیا دکھاتا ہے۔ گفتگو آپ کے اور دوسرے شخص کے درمیان نجی رہتی ہے۔",
